CREATE TABLE user_appearance_preferences (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, theme VARCHAR(32) NOT NULL DEFAULT 'midnight-black', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT valid_theme CHECK (theme IN ('midnight-black','cyber-blue','neon-purple','toxic-green','crimson-gaming','golden-elite','arctic-frost','synthwave','inferno','titanium')));
